draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var F0 = p.f0, k = p.slope, xe = p.xend;

var xMax = 6.0;
var fvals = [];
var i, x, f;
var fHi = 1, fLo = -1;
for (i = 0; i <= 120; i++) {
  x = xMax * i / 120;
  f = F0 + k * x;
  if (f > fHi) fHi = f;
  if (f < fLo) fLo = f;
}
fHi = fHi * 1.2; fLo = fLo * 1.2;

var padL = W * 0.11, padR = W * 0.05, padT = H * 0.12, padB = H * 0.22;
var sx = (W - padL - padR) / xMax;
var sy = (H - padT - padB) / (fHi - fLo);
function X(v) { return padL + v * sx; }
function Y(v) { return H - padB - (v - fLo) * sy; }

ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(xMax), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(0), Y(fLo)); ctx.lineTo(X(0), Y(fHi)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("F (N)", X(0) - 4, Y(fHi) + 10);
ctx.fillText("x (m)", X(xMax) - 34, Y(0) + 16);
for (i = 1; i <= 6; i++) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(i), Y(0) - 3); ctx.lineTo(X(i), Y(0) + 3); ctx.stroke();
  ctx.fillStyle = C.faint;
  ctx.fillText("" + i, X(i) - 3, Y(0) + 16);
}

var steps = 160;
var dx = xe / steps;
var Wpos = 0, Wneg = 0;
for (i = 0; i < steps; i++) {
  x = dx * (i + 0.5);
  f = F0 + k * x;
  if (f >= 0) { Wpos += f * dx; } else { Wneg += f * dx; }
}
var Wtot = Wpos + Wneg;

for (i = 0; i < steps; i++) {
  x = dx * i;
  f = F0 + k * (x + dx / 2);
  ctx.fillStyle = f >= 0 ? C.accent : C.figure;
  ctx.globalAlpha = 0.25;
  var yTop = Y(Math.max(f, 0)), yBot = Y(Math.min(f, 0));
  ctx.fillRect(X(x), yTop, Math.max(sx * dx + 0.6, 0.6), Math.max(yBot - yTop, 0));
  ctx.globalAlpha = 1;
}

ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 120; i++) {
  x = xMax * i / 120;
  f = F0 + k * x;
  if (i === 0) { ctx.moveTo(X(x), Y(f)); } else { ctx.lineTo(X(x), Y(f)); }
}
ctx.stroke();

ctx.strokeStyle = C.rule; ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(X(xe), Y(fLo)); ctx.lineTo(X(xe), Y(fHi)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("finish x = " + xe.toFixed(1) + " m", X(xe) + 5, Y(fHi) + 12);

ctx.fillStyle = C.ink;
ctx.fillText("F = " + F0.toFixed(1) + (k >= 0 ? " + " : " − ") + Math.abs(k).toFixed(1) + " x", padL, H * 0.09);

ctx.fillStyle = C.faint;
ctx.fillText("shaded area = work done", padL, H - 4);

out.note = "positive area " + Wpos.toFixed(2) + " J, negative area " + Wneg.toFixed(2) + " J, total work " + Wtot.toFixed(2) + " J";
